```js
// npm install escodegen estree-util
const escodegen = require('escodegen');
const { visit } = require('estree-util');

/**
 * Transforms an ESTree AST and returns the generated JavaScript code.
 *
 * @param {Object} ast - The input ESTree AST.
 * @param {Function} [transform] - Optional visitor function to modify nodes.
 * @returns {string} The generated JavaScript code.
 */
function generateCodeFromAst(ast, transform) {
  // If a transform function is supplied, walk the tree and apply it.
  if (typeof transform === 'function') {
    visit(ast, {
      // The visitor receives the current node and its parent.
      enter(node, parent) {
        transform(node, parent);
      },
    });
  }

  // Generate code from the (possibly transformed) AST.
  return escodegen.generate(ast, {
    format: {
      indent: { style: '  ' },
      semicolons: true,
    },
  });
}

/* Example usage */

// Sample AST: const x = 42;
const sampleAst = {
  type: 'Program',
  body: [
    {
      type: 'VariableDeclaration',
      declarations: [
        {
          type: 'VariableDeclarator',
          id: { type: 'Identifier', name: 'x' },
          init: { type: 'Literal', value: 42, raw: '42' },
        },
      ],
      kind: 'const',
    },
  ],
  sourceType: 'module',
};

// Optional transform: rename all identifiers named 'x' to 'y'.
function renameXtoY(node) {
  if (node.type === 'Identifier' && node.name === 'x') {
    node.name = 'y';
  }
}

const code = generateCodeFromAst(sampleAst, renameXtoY);
console.log(code);
// Output:
// const y = 42;
