```js
/**
 * Parses an ES module import statement (static or dynamic) and returns
 * an object with the parsed information.
 *
 * Supported forms:
 *   import defaultExport from 'module';
 *   import * as name from 'module';
 *   import { export1 , export2 as alias } from 'module';
 *   import 'module';
 *   import('module').then(...);
 *
 * @param {string} code - The import statement to parse.
 * @returns {Object|null} Parsed information or null if not an import.
 *   {
 *     type: 'static' | 'dynamic',
 *     module: string,
 *     imports: Array<string>   // empty for side‑effect imports
 *   }
 */
function parseImportStatement(code) {
  const trimmed = code.trim();

  // Dynamic import: import('module')
  const dynamicRe = /^import\s*\(\s*['"]([^'"]+)['"]\s*\)/;
  const dynMatch = trimmed.match(dynamicRe);
  if (dynMatch) {
    return {
      type: 'dynamic',
      module: dynMatch[1],
      imports: [] // dynamic imports don't expose named imports in the statement itself
    };
  }

  // Static import
  // 1. import defaultExport from 'module';
  // 2. import * as name from 'module';
  // 3. import { export1 , export2 as alias } from 'module';
  // 4. import 'module';
  const staticRe = /^import\s+(.+?)\s+from\s+['"]([^'"]+)['"]\s*;?$/;
  const sideEffectRe = /^import\s+['"]([^'"]+)['"]\s*;?$/;

  let match = trimmed.match(staticRe);
  if (match) {
    const importClause = match[1].trim();
    const moduleName = match[2];
    const imports = [];

    // Handle named imports: { a, b as c }
    const namedRe = /{([^}]+)}/;
    const namedMatch = importClause.match(namedRe);
    if (namedMatch) {
      const namedList = namedMatch[1]
        .split(',')
        .map(s => s.trim())
        .filter(Boolean);
      namedList.forEach(item => {
        const parts = item.split(/\s+as\s+/);
        imports.push(parts[0]); // use the original export name
      });
    }

    // Handle default import
    if (!namedRe.test(importClause)) {
      const defaultImport = importClause.replace(/\s*\*\s*as\s*\w+/, '').trim();
      if (defaultImport && defaultImport !== '*') {
        imports.push(defaultImport);
      }
    }

    // Handle namespace import: * as name
    if (importClause.startsWith('* as ')) {
      imports.push('*'); // indicate namespace import
    }

    return {
      type: 'static',
      module: moduleName,
      imports
    };
  }

  // Side‑effect only import
  match = trimmed.match(sideEffectRe);
  if (match) {
    return {
      type: 'static',
      module: match[1],
      imports: []
    };
  }

  // Not an import statement
  return null;
}

// Example usage:
console.log(parseImportStatement("import { foo, bar as baz } from 'my-module';"));
// { type: 'static', module: 'my-module', imports: ['foo', 'bar'] }

console.log(parseImportStatement("import('dynamic-module').then(m => m.foo);"));
// { type: 'dynamic', module: 'dynamic-module', imports: [] }

console.log(parseImportStatement("import 'side-effect-module';"));
// { type: 'static', module: 'side-effect-module', imports: [] }
```

