// Plugin definition
function parseMarkdownPlugin() {
  return (file) => {
    // Parse the Markdown string into an AST
    const ast = remarkParser.parse(file.value);
    // Replace the file contents with the AST so Remark can process it
    file.contents = ast;
  };
}

