// eslint-plugin-testing-library-custom/rules/no-fire-event.js
"use strict";

module.exports = {
  meta: {
    type: "problem",
    docs: {
      description: "Disallow fireEvent, use userEvent instead",
      category: "Best Practices",
      recommended: false
    },
    fixable: "code",
    schema: []
  },
  create(context) {
    return {
      CallExpression(node) {
        if (
          node.callee.type === "MemberExpression" &&
          node.callee.object.name === "fireEvent"
        ) {
          context.report({
            node,
            message: "Use userEvent instead of fireEvent",
            fix(fixer) {
              const sourceCode = context.getSourceCode();
              const args = sourceCode.getText(node.arguments);
              return fixer.replaceText(node, `userEvent.${node.callee.property.name}(${args})`);
            }
          });
        }
      }
    };
  }
};
