// eslint-plugin-testing-library-custom/rules/require-wait-for.js
"use strict";

module.exports = {
  meta: {
    type: "problem",
    docs: {
      description: "Prefer waitFor over findBy queries",
      category: "Best Practices",
      recommended: false
    },
    fixable: "code",
