      CallExpression(node) {
        if (
          node.callee.type === "MemberExpression" &&
          node.callee.object.name === "screen" &&
          node.callee.property.name.startsWith("findBy")
        ) {
          context.report({
            node,
            message: `Use waitFor(() => screen.${node.callee.property.name}(...)) instead of ${node.callee.property.name}`,
            fix(fixer) {
              const sourceCode = context.getSourceCode();
              const args = sourceCode.getText(node.arguments);
              const query = node.callee.property.name;
              return fixer.replaceText(
                node,
                `await waitFor(() => screen.${query}(${args}))`
              );
            }
          });
        }
      }
    };
  }
};
