```javascript
#!/usr/bin/env node
/**
 * Simple Dependency Manager
 * Features:
 *   - Automatic version bump (major/minor/patch)
 *   - Semantic versioning checks
 *   - Vulnerability monitoring via `npm audit`
 *   - Fast installation/update using npm
 *
 * Usage:
 *   node depmanager.js install          # npm install
 *   node depmanager.js update           # npm update
 *   node depmanager.js audit            # npm audit
 *   node depmanager.js bump <type>      # bump version (major|minor|patch)
 */

const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');
const util = require('util');
const execAsync = util.promisify(exec);

/**
 * Run a shell command and stream output to console.
 */
async function runCommand(cmd, options = {}) {
  const { stdout, stderr } = await execAsync(cmd, options);
  if (stdout) process.stdout.write(stdout);
  if (stderr) process.stderr.write(stderr);
}

/**
 * Read and parse package.json.
 */
function readPackageJson() {
  const pkgPath = path.resolve(process.cwd(), 'package.json');
  if (!fs.existsSync(pkgPath)) {
    throw new Error('package.json not found in current directory.');
  }
  const data = fs.readFileSync(pkgPath, 'utf8');
  return JSON.parse(data);
}

/**
 * Write package.json.
 */
function writePackageJson(pkg) {
  const pkgPath = path.resolve(process.cwd(), 'package.json');
  const data = JSON.stringify(pkg, null, 2) + '\n';
  fs.writeFileSync(pkgPath, data, 'utf8');
}

/**
 * Simple semantic version comparison.
 * Returns 1 if v1 > v2, -1 if v1 < v2, 0 if equal.
 */
function compareSemver(v1, v2) {
  const parse = v => v.replace(/^v/, '').split('.').map(Number);
  const [a1, b1, c1] = parse(v1);
  const [a2, b2, c2] = parse(v2);
  if (a1 !== a2) return a1 > a2 ? 1 : -1;
  if (b1 !== b2) return b1 > b2 ? 1 : -1;
  if (c1 !== c2) return c1 > c2 ? 1 : -1;
  return 0;
}

/**
 * Bump version in package.json.
 * type: 'major' | 'minor' | 'patch'
 */
function bumpVersion(type) {
  const pkg = readPackageJson();
  const current = pkg.version || '0.0.0';
  const [major, minor, patch] = current.replace(/^v/, '').split('.').map(Number);
  let newVer;
  switch (type) {
    case 'major':
      newVer = `${major + 1}.0.0`;
      break;
    case 'minor':
      newVer = `${major}.${minor + 1}.0`;
      break;
    case 'patch':
      newVer = `${major}.${minor}.${patch + 1}`;
      break;
    default:
      throw new Error('Invalid bump type. Use major, minor, or patch.');
  }
  pkg.version = newVer;
  writePackageJson(pkg);
  console.log(`Version bumped from ${current} to ${newVer}`);
}

/**
 * Update dependencies to latest compatible versions.
 */
async function updateDependencies() {
  console.log('Updating dependencies...');
  await runCommand('npm update');
  console.log('Dependencies updated.');
}

/**
 * Install dependencies.
 */
async function installDependencies() {
  console.log('Installing dependencies...');
  await runCommand('npm install');
  console.log('Dependencies installed.');
}

/**
 * Run npm audit and display results.
 */
async function auditDependencies() {
  console.log('Running vulnerability audit...');
  await runCommand('npm audit --json', { maxBuffer: 1024 * 1024 });
}

/**
 * Main CLI dispatcher.
 */
async function main() {
  const args = process.argv.slice(2);
  const cmd = args[0];

  try {
    switch (cmd) {
      case 'install':
        await installDependencies();
        break;
      case 'update':
        await updateDependencies();
        break;
      case 'audit':
        await auditDependencies();
        break;
      case 'bump':
        const type = args[1];
        if (!type) throw new Error('Specify bump type: major, minor, or patch.');
        bumpVersion(type);
        break;
      default:
        console.log(`Unknown command: ${cmd}`);
        console.log('Available commands: install, update, audit, bump');
    }
  } catch (err) {
    console.error('Error:', err.message);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}
```

