// Import the libsass library
const libsass = require('libsass');

// Helper to create a wrapper for each function
function createWrapper(fn) {
  return function (...args) {
    // Example: log the call (optional)
    console.log(`Calling ${fn.name} with args:`, args);
    return fn.apply(this, args);
  };
}

// Build an object with wrapped functions
const wrappedLibsass = {};

Object.keys(libsass).forEach((key) => {
  const value = libsass[key];
  if (typeof value === 'function') {
    wrappedLibsass[key] = createWrapper(value);
  } else {
    wrappedLibsass[key] = value; // keep non-function exports unchanged
  }
});

module.exports = wrappedLibsass;
