```js
// index.js
const consolidate = require('consolidate');
const nodemailer = require('nodemailer');
const path = require('path');
require('dotenv').config();

/**
 * Render a template using the consolidation engine.
 * @param {string} engine - The template engine name (e.g., 'ejs', 'pug').
 * @param {string} templatePath - Path to the template file.
 * @param {object} data - Data to inject into the template.
 * @returns {Promise<string>} Rendered HTML string.
 */
async function renderTemplate(engine, templatePath, data = {}) {
  const fullPath = path.resolve(templatePath);
  if (!consolidate[engine]) {
    throw new Error(`Template engine "${engine}" is not supported.`);
  }
  return consolidate[engine](fullPath, data);
}

/**
 * Send an email via Forward Email using Nodemailer.
 * @param {object} mailOptions - Nodemailer mail options.
 * @returns {Promise<object>} Result of the send operation.
 */
async function sendEmail(mailOptions) {
  const transporter = nodemailer.createTransport({
    host: process.env.FORWARD_EMAIL_HOST || 'smtp.forwardemail.net',
    port: process.env.FORWARD_EMAIL_PORT || 587,
    secure: false,
    auth: {
      user: process.env.FORWARD_EMAIL_USER,
      pass: process.env.FORWARD_EMAIL_PASS
    }
  });

  return transporter.sendMail(mailOptions);
}

module.exports = {
  renderTemplate,
  sendEmail
};
```

