```javascript
// unicodeTrie.js

// 1. Import required modules
const icu = require('icu-js');          // ICU bindings for Unicode data
const Trie = require('javascript-trie'); // Generic trie implementation

/**
 * Node structure for the Unicode Trie.
 * Each node represents a range of code points.
 */
class UnicodeTrieNode {
  constructor(start, end) {
    this.start = start;          // Inclusive start of the range
    this.end = end;              // Inclusive end of the range
    this.children = [];          // Child nodes (sub‑ranges)
    this.metadata = {};          // Metadata for the range (if any)
  }

  /**
   * Find or create a child node that covers the given code point.
   * @param {number} cp - Code point to insert.
   * @returns {UnicodeTrieNode} - The child node covering cp.
   */
  getOrCreateChild(cp) {
    // Search for an existing child that covers cp
    for (const child of this.children) {
      if (cp >= child.start && cp <= child.end) {
        return child;
      }
    }
    // If not found, create a new child that covers only cp
    const newChild = new UnicodeTrieNode(cp, cp);
    this.children.push(newChild);
    return newChild;
  }

  /**
   * Recursively search for the node that contains the code point.
   * @param {number} cp - Code point to look up.
   * @returns {UnicodeTrieNode|null}
   */
  findNode(cp) {
    if (cp < this.start || cp > this.end) return null;
    for (const child of this.children) {
      const res = child.findNode(cp);
      if (res) return res;
    }
    return this; // If no child matches, this node is the match
  }
}

/**
 * Builds a Unicode Trie from a string of characters.
 * @param {string} str - Input string containing Unicode characters.
 * @returns {UnicodeTrieNode} - Root of the constructed trie.
 */
function buildUnicodeTrie(str) {
  const root = new UnicodeTrieNode(0, 0x10FFFF); // Full Unicode range

  for (const ch of str) {
    const cp = ch.codePointAt(0);
    const node = root.getOrCreateChild(cp);

    // Retrieve metadata from ICU
    const data = icu.getUnicodeData(ch); // { codePoint, name, category, ... }

    // Store metadata at the leaf node
    node.metadata = {
      codePoint: data.codePoint,
      name: data.name,
      category: data.category,
    };
  }

  return root;
}

/**
 * Unicode Trie wrapper providing lookup methods.
 */
class UnicodeTrie {
  constructor(root) {
    this.root = root;
  }

  /**
   * Lookup metadata for a single character.
   * @param {string} ch - Character to look up.
   * @returns {object|null} - Metadata object or null if not found.
   */
  lookup(ch) {
    const cp = ch.codePointAt(0);
    const node = this.root.findNode(cp);
    return node ? node.metadata : null;
  }

  /**
   * Get the code point of a character.
   * @param {string} ch
   * @returns {number|null}
   */
  getCodePoint(ch) {
    const meta = this.lookup(ch);
    return meta ? meta.codePoint : null;
  }

  /**
   * Get the Unicode name of a character.
   * @param {string} ch
   * @returns {string|null}
   */
  getName(ch) {
    const meta = this.lookup(ch);
    return meta ? meta.name : null;
  }

  /**
   * Get the Unicode category of a character.
   * @param {string} ch
   * @returns {string|null}
   */
  getCategory(ch) {
    const meta = this.lookup(ch);
    return meta ? meta.category : null;
  }
}

// 5. Export the module
module.exports = {
  buildUnicodeTrie,
  UnicodeTrie,
};
```

```javascript
#!/usr/bin/env node
/**
 * create-project.js
 *
 * Usage: node create-project.js <project-name>
 *
 * This script creates a new Node.js project directory, writes a basic
 * package.json, creates an index.js file, and installs a few essential
 * dependencies (express, dotenv, nodemon).
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// ---------- Configuration ----------
const essentialDependencies = [
  'express',
  'dotenv',
  'nodemon'
];

// ---------- Helper Functions ----------
function log(message) {
  console.log(`[create-project] ${message}`);
}

function createDirectory(dirPath) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
    log(`Created directory: ${dirPath}`);
  } else {
    log(`Directory already exists: ${dirPath}`);
  }
}

function writeFile(filePath, content) {
  fs.writeFileSync(filePath, content, 'utf8');
  log(`Created file: ${filePath}`);
}

function runCommand(command, cwd) {
  log(`Running command: ${command}`);
  execSync(command, { stdio: 'inherit', cwd });
}

// ---------- Main ----------
function main() {
  const args = process.argv.slice(2);
  if (args.length === 0) {
    console.error('Error: Project name is required.');
    console.error('Usage: node create-project.js <project-name>');
    process.exit(1);
  }

  const projectName = args[0];
  const projectRoot = path.resolve(process.cwd(), projectName);

  // 1. Create project directory
  createDirectory(projectRoot);

  // 2. Create package.json
  const packageJson = {
    name: projectName,
    version: '1.0.0',
    description: '',
    main: 'index.js',
    scripts: {
      start: 'node index.js',
      dev: 'nodemon index.js'
    },
    keywords: [],
    author: '',
    license: 'ISC',
    dependencies: {},
    devDependencies: {}
  };

  // 3. Write package.json
  const packageJsonPath = path.join(projectRoot, 'package.json');
  writeFile(packageJsonPath, JSON.stringify(packageJson, null, 2));

  // 4. Create index.js
  const indexJsContent = `require('dotenv').config();
const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

app.get('/', (req, res) => {
  res.send('Hello, world!');
});

app.listen(PORT, () => {
  console.log(\`Server is running on http://localhost:\${PORT}\`);
});
`;
  const indexJsPath = path.join(projectRoot, 'index.js');
  writeFile(indexJsPath, indexJsContent);

  // 5. Install dependencies
  runCommand(`npm init -y`, projectRoot); // Ensure package.json exists
  runCommand(`npm install ${essentialDependencies.join(' ')}`, projectRoot);

  log('Project setup complete!');
}

main();
```

