// eslint-plugin-directive-comments/rules/no-unnecessary-directive.js
"use strict";

const { ESLint } = require("eslint");

module.exports = {
  meta: {
    type: "suggestion",
    docs: {
      description: "Disallow directive comments that disable rules not used in the file",
      category: "Best Practices",
      recommended: false,
    },
    schema: [], // no options
    messages: {
      unnecessary: "Directive comment disables rule '{{ruleId}}' which is not used in this file.",
    },
  },

  create(context) {
    // Collect all rule IDs that are actually used in the file
    const usedRules = new Set();

    // Walk the AST and collect rule IDs from any ESLint comment that re-enables a rule
    // (this is a heuristic; a full implementation would need to parse the config)
    context.getSourceCode().getAllComments().forEach((comment) => {
      const text = comment.value.trim();
      if (text.startsWith("eslint-enable")) {
        const parts = text.split(/\s+/);
        parts.slice(1).forEach((id) => usedRules.add(id));
      }
    });

    // Helper to parse a directive comment
    function parseDirective(comment) {
      const text = comment.value.trim();
      if (!text.startsWith("eslint-disable")) return null;
      const parts = text.split(/\s+/);
      return parts.slice(1); // array of rule IDs
    }

    return {
      Program() {
        // Scan all comments for disable directives
        context.getSourceCode().getAllComments().forEach((comment) => {
          const disabledRules = parseDirective(comment);
          if (!disabledRules) return;

          disabledRules.forEach((ruleId) => {
            if (!usedRules.has(ruleId)) {
              context.report({
                node: comment,
                messageId: "unnecessary",
                data: { ruleId },
              });
            }
          });
        });
      },
    };
  },
};
```

```js
// eslint-plugin-directive-comments/rules/no-missing-directive.js
"use strict";

module.exports = {
  meta: {
    type: "problem",
    docs: {
      description: "Disallow missing directive comments for rules that are globally disabled but used in the file",
      category: "Possible Errors",
      recommended: false,
    },
    schema: [], // no options
    messages: {
      missing: "Rule '{{ruleId}}' is globally disabled but used in this file. Add an eslint-enable directive.",
    },
  },

  create(context) {
    // This rule assumes that the global config is available via context.settings
    // In a real implementation you would read the ESLint configuration.
    const globalDisabled = context.settings && context.settings.eslintDisabledRules
      ? new Set(context.settings.eslintDisabledRules)
      : new Set();

    // Collect rules used in the file
    const usedRules = new Set();

    // Simple heuristic: look for any identifier that matches a rule name
    // (in practice you would need a more robust approach)
    context.getSourceCode().getAllComments().forEach((comment) => {
      const text = comment.value.trim();
      if (text.startsWith("eslint-disable")) {
        const parts = text.split(/\s+/);
        parts.slice(1).forEach((id) => usedRules.add(id));
      }
    });

    return {
      Identifier(node) {
        const name = node.name;
        if (globalDisabled.has(name) && !usedRules.has(name)) {
          context.report({
            node,
            messageId: "missing",
            data: { ruleId: name },
          });
        }
      },
    };
  },
};
```

```js
// eslint-plugin-directive-comments/rules/no-incorrect-directive.js
"use strict";

module.exports = {
  meta: {
    type: "problem",
    docs: {
      description: "Disallow incorrectly formatted or invalid ESLint directive comments",
      category: "Possible Errors",
      recommended: false,
    },
    schema: [], // no options
    messages: {
      invalidSyntax: "Invalid ESLint directive syntax: '{{text}}'.",
      unknownRule: "Unknown ESLint rule '{{ruleId}}' in directive comment.",
    },
  },

  create(context) {
    const validRuleIds = new Set(
      Object.keys(context.getSourceCode().parserServices?.esTreeNodeToTSNodeMap || {})
    ); // placeholder – in practice load from eslint rules

    function isValidDirective(text) {
      // Basic regex for eslint-disable / eslint-enable
      const regex = /^(eslint-(disable|enable))(\s+[\w-]+(\s+[\w-]+)*)?$/;
      return regex.test(text);
    }

    return {
      Program() {
        context.getSourceCode().getAllComments().forEach((comment) => {
          const text = comment.value.trim();
          if (!text.startsWith("eslint-")) return;

          if (!isValidDirective(text)) {
            context.report({
              node: comment,
              messageId: "invalidSyntax",
              data: { text },
            });
            return;
          }

          const parts = text.split(/\s+/);
          const ruleIds = parts.slice(1);
          ruleIds.forEach((ruleId) => {
            if (!validRuleIds.has(ruleId)) {
              context.report({
                node: comment,
                messageId: "unknownRule",
                data: { ruleId },
              });
            }
          });
        });
      },
    };
  },
};
```

