```js
#!/usr/bin/env node
/**
 * storybook-cli.js
 * A simple CLI to add Storybook to new or existing projects.
 * Requires: Node.js, npm, and the `inquirer` package.
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const inquirer = require('inquirer');

async function runCommand(cmd, cwd = process.cwd()) {
  try {
    execSync(cmd, { stdio: 'inherit', cwd });
  } catch (err) {
    console.error(`Error running command: ${cmd}`);
    process.exit(1);
  }
}

async function createNewProject(projectName, template) {
  const projectPath = path.resolve(process.cwd(), projectName);
  if (fs.existsSync(projectPath)) {
    console.error(`Directory ${projectName} already exists.`);
    process.exit(1);
  }
  fs.mkdirSync(projectPath);
  console.log(`Creating new ${template} project: ${projectName}`);
  runCommand('npm init -y', projectPath);
  runCommand(`npx create-${template} ${projectName}`, process.cwd());
  console.log('Installing Storybook...');
  runCommand(`npx sb init --type ${template}`, projectPath);
  return projectPath;
}

async function addStorybookToExisting(projectPath, template) {
  if (!fs.existsSync(projectPath)) {
    console.error(`Directory ${projectPath} does not exist.`);
    process.exit(1);
  }
  console.log(`Adding Storybook to existing project: ${projectPath}`);
  runCommand(`npx sb init --type ${template}`, projectPath);
}

async function configureStorybook(projectPath, addons) {
  const mainPath = path.join(projectPath, '.storybook', 'main.js');
  if (!fs.existsSync(mainPath)) {
    console.error('Storybook main.js not found. Did sb init run correctly?');
    process.exit(1);
  }
  const mainContent = fs.readFileSync(mainPath, 'utf8');
  const addonsArray = addons.map(a => `'${a}'`).join(', ');
  const newContent = mainContent.replace(
    /addons:\s*\[([^\]]*)\]/,
    `addons: [${addonsArray}]`
  );
  fs.writeFileSync(mainPath, newContent, 'utf8');
  console.log('Storybook configuration updated.');
}

async function main() {
  const { action } = await inquirer.prompt({
    type: 'list',
    name: 'action',
    message: 'What would you like to do?',
    choices: [
      { name: 'Create a new project with Storybook', value: 'new' },
      { name: 'Add Storybook to an existing project', value: 'add' },
    ],
  });

  const { template } = await inquirer.prompt({
    type: 'list',
    name: 'template',
    message: 'Select a project template:',
    choices: [
      { name: 'React', value: 'react' },
      { name: 'Vue', value: 'vue' },
      { name: 'Angular', value: 'angular' },
      { name: 'Svelte', value: 'svelte' },
      { name: 'Next.js', value: 'nextjs' },
      { name: 'Nuxt.js', value: 'nuxtjs' },
    ],
  });

  let projectPath;
  if (action === 'new') {
    const { projectName } = await inquirer.prompt({
      type: 'input',
      name: 'projectName',
      message: 'Enter the new project name:',
      validate: input => input ? true : 'Project name cannot be empty',
    });
    projectPath = await createNewProject(projectName, template);
  } else {
    const { existingPath } = await inquirer.prompt({
      type: 'input',
      name: 'existingPath',
      message: 'Enter the path to the existing project:',
      default: process.cwd(),
      validate: input => fs.existsSync(input) ? true : 'Path does not exist',
    });
    projectPath = path.resolve(existingPath);
    await addStorybookToExisting(projectPath, template);
  }

  const { addons } = await inquirer.prompt({
    type: 'checkbox',
    name: 'addons',
    message: 'Select Storybook addons to install:',
    choices: [
      { name: '@storybook/addon-actions', value: '@storybook/addon-actions' },
      { name: '@storybook/addon-links', value: '@storybook/addon-links' },
      { name: '@storybook/addon-essentials', value: '@storybook/addon-essentials' },
      { name: '@storybook/addon-interactions', value: '@storybook/addon-interactions' },
    ],
  });

  if (addons.length) {
    console.log('Installing selected addons...');
    runCommand(`npm install --save-dev ${addons.join(' ')}`, projectPath);
    await configureStorybook(projectPath, addons);
  }

  console.log('Storybook setup complete!');
}

main();
```

