// extensionManager.js
// A Node.js module for externalizing, localizing, compiling, and bundling VSCode extensions.

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const esbuild = require('esbuild');

const registry = new Map();

/**
 * Load extension metadata from a package.json or custom metadata file.
 * @param {string} extensionRoot - Root directory of the extension.
 * @returns {object} metadata
 */
function loadMetadata(extensionRoot) {
  const pkgPath = path.join(extensionRoot, 'package.json');
  if (!fs.existsSync(pkgPath)) {
    throw new Error(`package.json not found in ${extensionRoot}`);
  }
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
  const metadata = {
    name: pkg.name,
    version: pkg.version,
    publisher: pkg.publisher,
    contributes: pkg.contributes,
    dependencies: pkg.dependencies || {},
    scripts: pkg.scripts || {},
    main: pkg.main || 'out/extension.js',
    locale: pkg.locale || 'en',
  };
  return metadata;
}

/**
 * Register an extension's metadata in the registry.
 * @param {object} metadata
 */
function registerExtension(metadata) {
  if (!metadata.name) throw new Error('Extension metadata must have a name');
  registry.set(metadata.name, metadata);
}

/**
 * Ensure all dependencies are installed for the extension.
 * @param {string} extensionRoot
 * @param {object} dependencies
 */
function ensureDependencies(extensionRoot, dependencies) {
  const depNames = Object.keys(dependencies);
  if (depNames.length === 0) return;
  const depList = depNames.map((name) => `${name}@${dependencies[name]}`).join(' ');
  console.log(`Installing dependencies for ${extensionRoot}: ${depList}`);
  execSync(`npm install ${depList}`, { cwd: extensionRoot, stdio: 'inherit' });
}

/**
 * Compile TypeScript or JavaScript using esbuild.
 * @param {string} entryPoint - Path to the extension's main file.
 * @param {string} outDir - Output directory.
 * @param {object} [options] - esbuild options.
 */
async function compileExtension(entryPoint, outDir, options = {}) {
  const outFile = path.join(outDir, path.basename(entryPoint));
  await esbuild.build({
    entryPoints: [entryPoint],
    bundle: false,
    sourcemap: true,
    outdir: outDir,
    platform: 'node',
    target: ['node14'],
    format: 'cjs',
    ...options,
  });
  console.log(`Compiled ${entryPoint} -> ${outFile}`);
}

/**
 * Bundle the extension into a single file for distribution.
 * @param {string} entryPoint - Path to the extension's main file.
 * @param {string} outFile - Path to the bundled output file.
 * @param {object} [options] - esbuild options.
 */
async function bundleExtension(entryPoint, outFile, options = {}) {
  await esbuild.build({
    entryPoints: [entryPoint],
    bundle: true,
    minify: true,
    sourcemap: false,
    outfile: outFile,
    platform: 'node',
    target: ['node14'],
    format: 'cjs',
    ...options,
  });
  console.log(`Bundled ${entryPoint} -> ${outFile}`);
}

/**
 * Localize extension by replacing placeholders in package.json with locale-specific values.
 * @param {string} extensionRoot
 * @param {string} locale
 */
function localizeExtension(extensionRoot, locale) {
  const pkgPath = path.join(extensionRoot, 'package.json');
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
  if (!pkg.localizations) return;
  const loc = pkg.localizations[locale];
  if (!loc) throw new Error(`Locale ${locale} not found for ${pkg.name}`);
  Object.assign(pkg, loc);
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));
  console.log(`Localized ${pkg.name} to ${locale}`);
}

/**
 * Main function to process an extension directory.
 * @param {string} extensionRoot
 * @param {object} [options]
 */
async function processExtension(extensionRoot, options = {}) {
  const metadata = loadMetadata(extensionRoot);
  registerExtension(metadata);

  if (options.locale) {
    localizeExtension(extensionRoot, options.locale);
  }

  ensureDependencies(extensionRoot, metadata.dependencies);

  const srcMain = path.join(extensionRoot, metadata.main);
  const outDir = path.join(extensionRoot, 'dist');
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir);

  await compileExtension(srcMain, outDir, options.compileOptions);
  const bundleOut = path.join(extensionRoot, 'extension.bundle.js');
  await bundleExtension(srcMain, bundleOut, options.bundleOptions);
}

module.exports = {
  loadMetadata,
  registerExtension,
  ensureDependencies,
  compileExtension,
  bundleExtension,
  localizeExtension,
  processExtension,
  registry,
};
