const path = require('path');
const MiniCssExtractPlugin = require('mini-css-extract-plugin');

module.exports = {
  // Entry point for the Rails app
  entry: {
    application: path.resolve(__dirname, 'app/javascript/packs/application.js')
  },

  // Output bundled file to Rails public/packs
  output: {
    filename: '[name].js',
    path: path.resolve(__dirname, 'public/packs'),
    publicPath: '/packs/'
  },

  // Resolve module imports
  resolve: {
    extensions: ['.js', '.jsx', '.json'],
    alias: {
      // Example alias for easier imports
      '@components': path.resolve(__dirname, 'app/javascript/components/')
    }
  },

  module: {
    rules: [
      // Transpile JS/JSX with Babel
      {
        test: /\.(js|jsx)$/,
        exclude: /node_modules/,
        use: {
          loader: 'babel-loader',
          options: {
            presets: ['@babel/preset-env', '@babel/preset-react']
          }
        }
      },
      // Load CSS and extract into separate file
      {
        test: /\.css$/,
        use: [MiniCssExtractPlugin.loader, 'css-loader']
      },
      // Load images/fonts
      {
        test: /\.(png|jpe?g|gif|svg|woff2?|eot|ttf|otf)$/,
        type: 'asset/resource',
        generator: {
          filename: 'assets/[hash][ext][query]'
        }
      }
    ]
  },

  plugins: [
    new MiniCssExtractPlugin({
      filename: '[name].css'
    })
  ],

  // Enable source maps for easier debugging
  devtool: 'source-map',

  // Watch mode for development
  watch: process.env.NODE_ENV !== 'production'
};
