```javascript
/* ------------------------------------------------------------------
 * ISO 3166‑1 Country Code i18n + Number Formatting
 * ------------------------------------------------------------------ */

/* 1. Country code → translations mapping
 *    The object keys are ISO 3166‑1 alpha‑2 codes.
 *    Each value is an object whose keys are language codes
 *    (ISO 639‑1) and whose values are the translated country names.
 */
const countryTranslations = {
  US: { en: 'United States', fr: 'États‑Unis', es: 'Estados Unidos' },
  FR: { en: 'France',        fr: 'France',        es: 'Francia' },
  DE: { en: 'Germany',       fr: 'Allemagne',     es: 'Alemania' },
  JP: { en: 'Japan',         fr: 'Japon',         es: 'Japón' },
  CN: { en: 'China',         fr: 'Chine',         es: 'China' },
  BR: { en: 'Brazil',        fr: 'Brésil',        es: 'Brasil' },
  IN: { en: 'India',         fr: 'Inde',          es: 'India' },
  RU: { en: 'Russia',        fr: 'Russie',        es: 'Rusia' },
  // Add more countries as needed
};

/* 2. Get translated country name
 *    Parameters:
 *      code   – ISO 3166‑1 alpha‑2 country code (string)
 *      locale – BCP‑47 locale string (e.g., 'en-US', 'fr-FR')
 *    Returns:
 *      Translated country name if available, otherwise the code itself.
 */
function getCountryName(code, locale) {
  const lang = locale.split('-')[0]; // e.g., 'en' from 'en-US'
  const translations = countryTranslations[code.toUpperCase()];
  if (!translations) return code; // unknown code

  return translations[lang] || translations.en || code;
}

/* 3. Format a number according to the user's locale
 *    Parameters:
 *      value  – numeric value to format
 *      locale – BCP‑47 locale string
 *    Returns:
 *      Locale‑aware formatted string
 */
function formatNumber(value, locale) {
  return new Intl.NumberFormat(locale).format(value);
}

/* ------------------------------------------------------------------
 * Example usage
 * ------------------------------------------------------------------ */
const userLocale = navigator.language || 'en-US'; // e.g., 'fr-FR'

const countryCode = 'JP';
console.log(`Country (${countryCode}): ${getCountryName(countryCode, userLocale)}`);

const amount = 1234567.89;
console.log(`Formatted amount: ${formatNumber(amount, userLocale)}`);

/* ------------------------------------------------------------------
 * Export (for module usage)
 * ------------------------------------------------------------------ */
export { getCountryName, formatNumber, countryTranslations };
