```js
#!/usr/bin/env node
/**
 * generate-api.js
 *
 * A Node.js script that:
 *  1. Generates an API report, documentation, and .d.ts rollup for a TypeScript library
 *     using ts-api-generator and ts-doc.
 *  2. Outputs the results into a specified directory.
 *
 * Usage:
 *   node generate-api.js <path-to-ts-project> [output-directory]
 *
 * Dependencies:
 *   npm install -D ts-api-generator ts-doc
 */

const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

function runCommand(cmd, options = {}) {
  console.log(`\n> ${cmd}`);
  execSync(cmd, { stdio: 'inherit', ...options });
}

function ensureDir(dir) {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

/**
 * Generate API report + .d.ts rollup with ts-api-generator.
 * @param {string} projectPath - Path to the tsconfig.json of the library.
 * @param {string} outDir - Directory where the report and rollup will be written.
 */
function generateApiReport(projectPath, outDir) {
  ensureDir(outDir);
  const cmd = `npx ts-api-generator --project "${projectPath}" --output "${outDir}" --rollup`;
  runCommand(cmd);
}

/**
 * Generate documentation with ts-doc.
 * @param {string} projectPath - Path to the tsconfig.json of the library.
 * @param {string} outDir - Directory where the docs will be written.
 */
function generateDocs(projectPath, outDir) {
  ensureDir(outDir);
  const cmd = `npx ts-doc --project "${projectPath}" --output "${outDir}"`;
  runCommand(cmd);
}

function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    console.error('Usage: node generate-api.js <project-path> [output-directory]');
    process.exit(1);
  }

  const projectPath = path.resolve(args[0]);
  const outDir = args[1] ? path.resolve(args[1]) : path.resolve(projectPath, 'api-output');

  console.log(`Project path: ${projectPath}`);
  console.log(`Output directory: ${outDir}`);

  generateApiReport(projectPath, outDir);
  generateDocs(projectPath, outDir);

  console.log('\n✅ API report, documentation, and .d.ts rollup generated successfully.');
}

main();
