#!/usr/bin/env node
/**
 * cli.js – A simple CLI to scaffold, build, and deploy a React app
 * Usage:
 *   node cli.js init <app-name>   # Create a new CRA project
 *   node cli.js build <app-name>  # Build the project
 *   node cli.js deploy <app-name> # Deploy to GitHub Pages
 */

const { execSync } = require('child_process');
const { program } = require('commander');
const path = require('path');
const fs = require('fs');

// Helper to run shell commands
function run(cmd, cwd) {
  execSync(cmd, { stdio: 'inherit', cwd });
}

// Create a new CRA project
program
  .command('init <appName>')
  .description('Create a new React app using create-react-app')
  .action((appName) => {
    console.log(`Creating React app: ${appName}`);
    run(`npx create-react-app ${appName}`);
    console.log('Adding deploy script to package.json');
    const pkgPath = path.join(appName, 'package.json');
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
    pkg.scripts.deploy = 'gh-pages -d build';
    fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));
    console.log('Installing gh-pages');
    run('npm install gh-pages --save-dev', path.join(process.cwd(), appName));
    console.log('Done! Run "npm run deploy" inside the app folder to deploy.');
  });

// Build the app
program
  .command('build <appName>')
  .description('Build the React app')
  .action((appName) => {
    console.log(`Building ${appName}`);
    run('npm run build', path.join(process.cwd(), appName));
  });

// Deploy the app to GitHub Pages
program
  .command('deploy <appName>')
  .description('Deploy the React app to GitHub Pages')
  .action((appName) => {
    console.log(`Deploying ${appName}`);
    run('npm run deploy', path.join(process.cwd(), appName));
  });

program.parse(process.argv);
