// karma-firefox-launcher.js
const child_process = require('child_process');
const util = require('util');
const BaseLauncher = require('karma-launcher/lib/base-launcher');

function FirefoxLauncher(base, logger, helper, formatError) {
  BaseLauncher.call(this, base, logger, helper, formatError);
  this._base = base;
}

util.inherits(FirefoxLauncher, BaseLauncher);

FirefoxLauncher.prototype._doLaunch = function (done) {
  const logger = this._logger;
  const baseUrl = this._base.getUrl();

  // Arguments to launch Firefox with remote debugging enabled
  const args = [
    '--new-instance',
    '--no-remote',
    '--remote-debugging-port=9222',
    baseUrl
  ];

  // Resolve Firefox executable path
  const firefoxPath = this._base.getBrowserName() === 'firefox'
    ? 'firefox'
    : this._base.getBrowserName();

  const child = child_process.spawn(firefoxPath, args, {
    stdio: 'ignore',
    detached: true
  });

  child.on('error', (err) => {
    logger.error('Failed to launch Firefox: %s', err);
    done(err);
  });

  // Detach so the process continues after Karma exits
  child.unref();

  // Ensure Firefox is killed when Karma exits
  this._base.on('close', () => {
    child.kill();
  });

  done();
};

module.exports = {
  'launcher:firefox': ['type', FirefoxLauncher]
};
