```js
// npm install typescript-parser
// npm install estree

const tsParser = require('typescript-parser');
const { parse } = tsParser;

// Simple ESTree node factory (plain objects)
function createNode(type, props = {}) {
  return { type, ...props };
}

function tsNodeToESTree(tsNode) {
  if (!tsNode) return null;

  switch (tsNode.type) {
    case 'Program':
      return createNode('Program', {
        body: tsNode.body.map(tsNodeToESTree),
        sourceType: 'module',
      });

    case 'FunctionDeclaration':
      return createNode('FunctionDeclaration', {
        id: tsNode.id ? tsNodeToESTree(tsNode.id) : null,
        params: tsNode.params.map(tsNodeToESTree),
        body: tsNodeToESTree(tsNode.body),
        generator: false,
        async: false,
        expression: false,
      });

    case 'VariableDeclaration':
      return createNode('VariableDeclaration', {
        declarations: tsNode.declarations.map(tsNodeToESTree),
        kind: tsNode.kind,
      });

    case 'VariableDeclarator':
      return createNode('VariableDeclarator', {
        id: tsNodeToESTree(tsNode.id),
        init: tsNode.init ? tsNodeToESTree(tsNode.init) : null,
      });

    case 'Identifier':
      return createNode('Identifier', { name: tsNode.name });

    case 'Literal':
      return createNode('Literal', {
        value: tsNode.value,
        raw: tsNode.raw,
      });

    case 'BlockStatement':
      return createNode('BlockStatement', {
        body: tsNode.body.map(tsNodeToESTree),
      });

    case 'ExpressionStatement':
      return createNode('ExpressionStatement', {
        expression: tsNodeToESTree(tsNode.expression),
      });

    case 'ReturnStatement':
      return createNode('ReturnStatement', {
        argument: tsNode.argument ? tsNodeToESTree(tsNode.argument) : null,
      });

    case 'BinaryExpression':
      return createNode('BinaryExpression', {
        operator: tsNode.operator,
        left: tsNodeToESTree(tsNode.left),
        right: tsNodeToESTree(tsNode.right),
      });

    case 'CallExpression':
      return createNode('CallExpression', {
        callee: tsNodeToESTree(tsNode.callee),
        arguments: tsNode.arguments.map(tsNodeToESTree),
      });

    // Add more node type mappings as needed

    default:
      // For unhandled node types, return null or throw an error
      return null;
  }
}

function parseTStoESTree(tsSource) {
  const tsAst = parse(tsSource);
  return tsNodeToESTree(tsAst);
}

module.exports = { parseTStoESTree };
```

