```js
// Requires: npm install acorn acorn-walk
const acorn = require('acorn');
const walk = require('acorn-walk');

/**
 * Parses JavaScript source code and returns an array of imported modules
 * with their corresponding imported names.
 *
 * @param {string} code - The JavaScript source code to analyze.
 * @returns {Array<{module: string, names: Array<string> | null}>}
 *   Each element represents an import:
 *     - `module`: the module specifier string.
 *     - `names`: an array of imported identifiers for static imports,
 *       or `null` for dynamic imports.
 */
function parseImports(code) {
  const ast = acorn.parse(code, {
    ecmaVersion: 'latest',
    sourceType: 'module',
  });

  const imports = [];

  walk.simple(ast, {
    ImportDeclaration(node) {
      const module = node.source.value;
      const names = [];

      node.specifiers.forEach((spec) => {
        if (spec.type === 'ImportDefaultSpecifier') {
          names.push('default');
        } else if (spec.type === 'ImportNamespaceSpecifier') {
          names.push('*');
        } else if (spec.type === 'ImportSpecifier') {
          names.push(spec.imported.name);
        }
      });

      imports.push({ module, names });
    },

    ImportExpression(node) {
      // Only handle string literal arguments
      if (node.source.type === 'Literal' && typeof node.source.value === 'string') {
        imports.push({ module: node.source.value, names: null });
      } else {
        // Dynamic import with non‑literal argument – skip or mark as unknown
        imports.push({ module: '<dynamic>', names: null });
      }
    },
  });

  return imports;
}

// Example usage:
const code = `
import defaultExport from 'module-a';
import { named1, named2 as alias } from "module-b";
import * as ns from 'module-c';
import 'module-d';

async function load() {
  const mod = await import('module-e');
  const nested = await import('module-f').then(m => import('module-g'));
}
`;

console.log(parseImports(code));
/*
[
  { module: 'module-a', names: [ 'default' ] },
  { module: 'module-b', names: [ 'named1', 'named2' ] },
  { module: 'module-c', names: [ '*' ] },
  { module: 'module-d', names: [ 'default' ] },
  { module: 'module-e', names: null },
  { module: 'module-f', names: null },
  { module: 'module-g', names: null }
]
*/
```

```javascript
/**
 * Parses import statements with module assertions in the given JavaScript code.
 * Returns an array of objects: { source: string, assertions: object }.
 *
 * Example:
 *   const code = `
 *     import foo from 'foo.json' assert { type: 'json' };
 *     import 'bar.js' assert { type: 'script' };
 *   `;
 *   console.log(parseImportAssertions(code));
 *   // [
 *   //   { source: 'foo.json', assertions: { type: 'json' } },
 *   //   { source: 'bar.js', assertions: { type: 'script' } }
 *   // ]
 */
function parseImportAssertions(code) {
  const importRegex = /import\s+(?:[^;]*?)\s+from\s+(['"`])([^'"`]+)\1\s+assert\s*\{([^}]+)\}|import\s+(['"`])([^'"`]+)\4\s+assert\s*\{([^}]+)\}/g;
  const results = [];
  let match;
  while ((match = importRegex.exec(code)) !== null) {
    const source = match[2] || match[5];
    const attrString = match[3] || match[6];
    const assertions = parseAssertionAttributes(attrString);
    results.push({ source, assertions });
  }
  return results;
}

function parseAssertionAttributes(attrString) {
  const attrs = {};
  const pairRegex = /(\w+)\s*:\s*(['"`]?)([^'"`]+?)\2/g;
  let m;
  while ((m = pairRegex.exec(attrString)) !== null) {
    const key = m[1];
    const value = m[3];
    attrs[key] = value;
  }
  return attrs;
}

// Example usage:
const code = `
  import foo from 'foo.json' assert { type: 'json' };
  import 'bar.js' assert { type: 'script', version: '1.0' };
  import * as mod from 'mod.js' assert { type: 'module' };
`;

console.log(parseImportAssertions(code));
```

