// Install dependencies: npm install sockjs-node express
const express = require('express');
const http = require('http');
const sockjs = require('sockjs-node');

const app = express();
const server = http.createServer(app);

// Create a SockJS server
const sockjsOpts = { sockjs_url: 'https://cdn.jsdelivr.net/npm/sockjs-client@1/dist/sockjs.min.js' };
const sockjsServer = sockjs.createServer(sockjsOpts);

// Handle connections
sockjsServer.on('connection', conn => {
  console.log('Client connected:', conn.id);

  // Echo received messages back to the client
  conn.on('data', message => {
    console.log('Received:', message);
    conn.write(`Echo: ${message}`);
  });

  conn.on('close', () => {
    console.log('Client disconnected:', conn.id);
  });
});

// Attach SockJS server to the HTTP server
sockjsServer.installHandlers(server, { prefix: '/ws' });

// Start listening
const PORT = 8080;
server.listen(PORT, () => {
  console.log(`SockJS server listening on http://localhost:${PORT}/ws`);
});
