```javascript
// src/logger.js
/**
 * Simple logger utility.
 * Supports log levels: debug, info, warn, error.
 * Can be extended to write to files or external services.
 */
class Logger {
  constructor(level = 'info') {
    this.levels = { debug: 0, info: 1, warn: 2, error: 3 };
    this.currentLevel = this.levels[level] ?? this.levels.info;
  }

  log(level, ...args) {
    if (this.levels[level] >= this.currentLevel) {
      const prefix = `[${level.toUpperCase()}]`;
      console.log(prefix, ...args);
    }
  }

  debug(...args) { this.log('debug', ...args); }
  info(...args)  { this.log('info',  ...args); }
  warn(...args)  { this.log('warn',  ...args); }
  error(...args) { this.log('error', ...args); }
}

export default new Logger();
```

```javascript
// src/configService.js
/**
 * Configuration service.
 * Loads configuration from environment variables or defaults.
 * Exposes a get(key) method for retrieving config values.
 */
class ConfigService {
  constructor() {
    this.config = {
      apiBaseUrl: process.env.API_BASE_URL || 'https://api.example.com',
      timeout: parseInt(process.env.TIMEOUT, 10) || 5000,
      featureFlags: {
        enableNewFeature: process.env.ENABLE_NEW_FEATURE === 'true',
      },
      // Add more default config values here
    };
  }

  get(key, defaultValue = undefined) {
    const keys = key.split('.');
    let value = this.config;
    for (const k of keys) {
      if (value && k in value) {
        value = value[k];
      } else {
        return defaultValue;
      }
    }
    return value;
  }

  set(key, value) {
    const keys = key.split('.');
    let obj = this.config;
    for (let i = 0; i < keys.length - 1; i++) {
      const k = keys[i];
      if (!(k in obj)) obj[k] = {};
      obj = obj[k];
    }
    obj[keys[keys.length - 1]] = value;
  }
}

export default new ConfigService();
