import { useSync } from 'use-sync';

/** External store interface */
export interface ExternalStore<T> {
  /** Return the current state */
  getState(): T;
  /** Replace the current state */
  setState(state: T): void;
  /** Subscribe to state changes. Returns an unsubscribe function. */
  subscribe(listener: (state: T) => void): () => void;
}

/** Configuration for creating a store */
export interface StoreConfig<T> {
  /** Initial state of the store */
  initialState: T;
  /** Optional callback invoked after every state change */
  onChange?: (state: T) => void;
}

/** State returned by the `useExternalStore` hook */
export interface StoreState<T> {
  /** Current state value */
  state: T;
  /** Setter that updates the state */
  setState: (state: T) => void;
}

/** Actions exposed by the store */
export interface StoreActions<T> {
  /** Get the current state */
  get: () => T;
  /** Set a new state */
  set: (state: T) => void;
  /** Subscribe to state changes */
  subscribe: (listener: (state: T) => void) => () => void;
}

/** Create a simple external store */
export function createExternalStore<T>(config: StoreConfig<T>): ExternalStore<T> {
  let state = config.initialState;
  const listeners: Array<(state: T) => void> = [];

  const getState = () => state;
  const setState = (newState: T) => {
    state = newState;
    listeners.forEach((l) => l(state));
    config.onChange?.(state);
  };
  const subscribe = (listener: (state: T) => void) => {
    listeners.push(listener);
    return () => {
      const idx = listeners.indexOf(listener);
      if (idx > -1) listeners.splice(idx, 1);
    };
  };

  return { getState, setState, subscribe };
}

/** Hook that syncs a component with an external store */
export function useExternalStore<T>(store: ExternalStore<T>): StoreState<T> {
  const [state, setState] = useSync(store.getState(), (newState) => store.setState(newState));
  return { state, setState };
}

