// npm install escodegen estree-util
const escodegen = require('escodegen');
const { visit } = require('estree-util');

/**
 * Transforms an AST (e.g., rename all identifiers that match a pattern)
 * and returns the generated JavaScript code.
 *
 * @param {Object} ast - The ESTree-compliant AST.
 * @param {Object} options - Transformation options.
 * @param {RegExp} [options.renamePattern] - Pattern to match identifiers to rename.
 * @param {string} [options.renameTo] - New name for matched identifiers.
 * @returns {string} Generated JavaScript code.
 */
function transformAndGenerate(ast, options = {}) {
  const { renamePattern, renameTo } = options;

  // Traverse the AST and apply transformations
  visit(ast, {
    // Called for every node
    enter(node) {
      // Example: rename identifiers that match the pattern
      if (
        renamePattern &&
        renameTo &&
        node.type === 'Identifier' &&
        renamePattern.test(node.name)
      ) {
        node.name = renameTo;
      }
    },
  });

  // Generate code from the (possibly transformed) AST
  return escodegen.generate(ast, {
    format: { indent: { style: '  ' }, semicolons: true },
  });
}

// Example usage:

// Sample AST (parsed from source code)
const sampleAst = {
  type: 'Program',
  body: [
    {
      type: 'VariableDeclaration',
      declarations: [
        {
          type: 'VariableDeclarator',
          id: { type: 'Identifier', name: 'foo' },
          init: { type: 'Literal', value: 42, raw: '42' },
        },
      ],
      kind: 'const',
    },
    {
      type: 'ExpressionStatement',
      expression: {
        type: 'CallExpression',
        callee: { type: 'Identifier', name: 'console.log' },
        arguments: [{ type: 'Identifier', name: 'foo' }],
      },
    },
  ],
  sourceType: 'module',
};

// Transform: rename all identifiers named 'foo' to 'bar'
const generatedCode = transformAndGenerate(sampleAst, {
  renamePattern: /^foo$/,
  renameTo: 'bar',
});

console.log(generatedCode);

/*
Expected output:

const bar = 42;
console.log(bar);
*/
