const evaluateBundle = require('metro-evaluator');
const fs = require('fs').promises;

/**
 * Evaluates a Metro bundle file and returns the result.
 *
 * @param {string} bundlePath - Path to the Metro bundle file.
 * @returns {Promise<any>} The evaluation result.
 */
async function evaluateMetroBundle(bundlePath) {
  const bundle = await fs.readFile(bundlePath, 'utf8');
  const result = await evaluateBundle(bundle);
  return result;
}

module.exports = evaluateMetroBundle;
