// bundle-react-native.js
//
// This script bundles all React Native modules and their dependencies
// into a single production‑ready bundle using react-native-bundle-anner.
// It assumes that `react-native-bundle-anner` is installed locally
// (e.g., `npm install react-native-bundle-anner --save-dev`).

const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

// Configuration -----------------------------------------------------------

const projectRoot = process.cwd(); // current working directory
const entryFile = path.join(projectRoot, 'index.js'); // adjust if your entry file differs
const outputDir = path.join(projectRoot, 'dist');
const outputFile = path.join(outputDir, 'index.bundle');

// Ensure output directory exists
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Build command -----------------------------------------------------------

const bundleCommand = [
  'npx', // use local binary
  'react-native-bundle-anner',
  '--entry-file', entryFile,
  '--bundle-output', outputFile,
  '--dev', 'false',          // production mode
  '--minify', 'true',        // minify the bundle
  '--platform', 'ios',       // or 'android' as needed
  '--assets-dest', outputDir // copy assets to the same folder
].join(' ');

// Execute -----------------------------------------------------------

try {
  console.log('Bundling React Native app for production...');
  execSync(bundleCommand, { stdio: 'inherit' });
  console.log(`✅ Bundle created at ${outputFile}`);
} catch (err) {
  console.error('❌ Bundling failed:', err);
  process.exit(1);
}
