// escodegen-interfaces.ts
import { Node } from 'estree';

export interface Grammar {
  // Define grammar structure as needed
  [key: string]: any;
}

export interface Code {
  ast: Node;
  toString(): string;
}

export interface FunctionCode extends Code {
  name: string;
  params: string[];
  body: Node[];
}

export interface VariableCode extends Code {
  name: string;
  init?: Node;
}

export interface ControlFlowCode extends Code {
  type: 'IfStatement' | 'ForStatement' | 'WhileStatement' | 'SwitchStatement';
  test?: Node;
  consequent?: Node;
  alternate?: Node;
  body?: Node[];
}

export interface CodeGenerator {
  generate(grammar: Grammar): Code[];
}
