// opentelemetry-async-context.js
import { diag, DiagConsoleLogger, DiagLogLevel } from '@opentelemetry/api';
import { NodeTracerProvider } from '@opentelemetry/sdk-trace-node';
import { NodeMeterProvider } from '@opentelemetry/sdk-metrics-node';
import { NodeLoggerProvider } from '@opentelemetry/sdk-logs';
import { AsyncHooksContextManager } from '@opentelemetry/context-async-hooks';
import { registerInstrumentations } from '@opentelemetry/instrumentation';
import { ConsoleSpanExporter, SimpleSpanProcessor } from '@opentelemetry/sdk-trace-base';
import { ConsoleMetricExporter, PeriodicExportingMetricReader } from '@opentelemetry/sdk-metrics-base';
import { ConsoleLogRecordExporter, PeriodicExportingLogRecordProcessor } from '@opentelemetry/sdk-logs';
import { HttpInstrumentation } from '@opentelemetry/instrumentation-http';
import { ExpressInstrumentation } from '@opentelemetry/instrumentation-express';

// Enable diagnostics logging (optional)
diag.setLogger(new DiagConsoleLogger(), DiagLogLevel.INFO);

// ---------- Context Manager ----------
const contextManager = new AsyncHooksContextManager();
contextManager.enable();
diag.info('AsyncHooksContextManager enabled');

// ---------- Tracing ----------
const tracerProvider = new NodeTracerProvider();
tracerProvider.addSpanProcessor(new SimpleSpanProcessor(new ConsoleSpanExporter()));
tracerProvider.register();
diag.info('TracerProvider registered');

// ---------- Metrics ----------
const meterProvider = new NodeMeterProvider();
meterProvider.addMetricReader(
  new PeriodicExportingMetricReader({
    exporter: new ConsoleMetricExporter(),
    exportIntervalMillis: 5000,
  })
);
meterProvider.register();
diag.info('MeterProvider registered');

// ---------- Logs ----------
const loggerProvider = new NodeLoggerProvider();
loggerProvider.addLogRecordProcessor(
  new PeriodicExportingLogRecordProcessor({
    exporter: new ConsoleLogRecordExporter(),
    exportIntervalMillis: 5000,
  })
);
loggerProvider.register();
diag.info('LoggerProvider registered');

// ---------- Instrumentations ----------
registerInstrumentations({
  instrumentations: [
    new HttpInstrumentation(),
    new ExpressInstrumentation(),
  ],
  tracerProvider,
  meterProvider,
  loggerProvider,
});

// ---------- Exported API ----------
export const tracer = tracerProvider.getTracer('example-tracer');
export const meter = meterProvider.getMeter('example-meter');
export const logger = loggerProvider.getLogger('example-logger');
export const context = contextManager;
