```js
// gipsicle-wrapper.js
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');

/**
 * Runs the local `gipsicle` binary with the provided arguments.
 *
 * @param {...string} args - Arguments to pass to gipsicle.
 * @returns {Promise<void>} Resolves when the command exits successfully.
 */
function gipsicle(...args) {
  // Resolve the path to the local gipsicle binary
  const binPath = path.resolve(
    __dirname,
    'node_modules',
    '.bin',
    process.platform === 'win32' ? 'gipsicle.cmd' : 'gipsicle'
  );

  if (!fs.existsSync(binPath)) {
    throw new Error(
      'gipsicle binary not found. Install it with `npm install gipsicle`.'
    );
  }

  return new Promise((resolve, reject) => {
    const child = spawn(binPath, args, {
      stdio: 'inherit',
      shell: true,
    });

    child.on('close', (code) => {
      if (code === 0) {
        resolve();
      } else {
        reject(new Error(`gipsicle exited with code ${code}`));
      }
    });

    child.on('error', (err) => {
      reject(err);
    });
  });
}

module.exports = gipsicle;
