```js
// gipsicle-wrapper.js
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');

/**
 * Locate the gipsicle binary.
 * @returns {string} Absolute path to the gipsicle executable.
 * @throws {Error} If the binary cannot be found.
 */
function findGipsicle() {
  // 1. Try local installation: node_modules/.bin/gipsicle
  const localPath = path.resolve(process.cwd(), 'node_modules', '.bin', 'gipsicle');
  if (fs.existsSync(localPath)) {
    return localPath;
  }

  // 2. Try global installation via require.resolve
  try {
    return require.resolve('gipsicle/bin/gipsicle');
  } catch (_) {
    // Not found
  }

  throw new Error(
    'gipsicle binary not found. Install it locally with "npm install gipsicle" or globally.'
  );
}

/**
 * Run the gipsicle command with the given arguments.
 *
 * @param {string[]} args - Arguments to pass to gipsicle.
 * @param {Object} [options] - Optional settings.
 * @param {string} [options.cwd] - Working directory for the command.
 * @param {Object} [options.env] - Environment variables for the command.
 * @returns {Promise<string>} Resolves with stdout on success, rejects on error.
 */
function runGipsicle(args = [], options = {}) {
  const gipsiclePath = findGipsicle();

  return new Promise((resolve, reject) => {
    const child = spawn(gipsiclePath, args, {
      stdio: ['ignore', 'pipe', 'pipe'],
      cwd: options.cwd || process.cwd(),
      env: { ...process.env, ...(options.env || {}) },
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', chunk => (stdout += chunk));
    child.stderr.on('data', chunk => (stderr += chunk));

    child.on('close', code => {
      if (code === 0) {
        resolve(stdout);
      } else {
        const err = new Error(`gipsicle exited with code ${code}`);
        err.code = code;
        err.stdout = stdout;
        err.stderr = stderr;
        reject(err);
      }
    });

    child.on('error', err => reject(err));
  });
}

module.exports = runGipsicle;
```

```js
// build.js
// Run with: node build.js

const path = require('path');
const fs = require('fs');
const { analyze } = require('ts-analysis');
const { generateDocs } = require('ts-doc');
const { rollup } = require('rollup');
const dts = require('rollup-plugin-dts');

// ---------- 1. Analyze exported API ----------
async function analyzeAPI() {
  const tsconfigPath = path.resolve(__dirname, 'tsconfig.json');
  const { program } = analyze(tsconfigPath);
  const exports = program.getSourceFiles()
    .filter(sf => !sf.isDeclarationFile)
    .flatMap(sf => sf.getExportedDeclarations())
    .map(([name, decls]) => ({ name, decls }));

  // Simple review: list exported symbols
  const review = exports.map(e => e.name).join('\n');
  fs.writeFileSync('api-review.txt', review);
  console.log('API review written to api-review.txt');
  return exports;
}

// ---------- 2. Generate documentation ----------
async function generateDocumentation() {
  const docsDir = path.resolve(__dirname, 'docs');
  if (!fs.existsSync(docsDir)) fs.mkdirSync(docsDir);
  await generateDocs({
    tsconfig: 'tsconfig.json',
    outDir: docsDir,
    include: ['src/**/*.ts'],
  });
  console.log('Documentation generated in docs/');
}

// ---------- 3. Rollup JS bundle ----------
async function bundleJS() {
  const bundle = await rollup({
    input: 'src/index.ts',
    plugins: [],
  });
  await bundle.write({
    file: 'dist/bundle.js',
    format: 'cjs',
    sourcemap: true,
  });
  console.log('JS bundle written to dist/bundle.js');
}

// ---------- 4. Rollup .d.ts bundle ----------
async function bundleDTS() {
  const bundle = await rollup({
    input: 'src/index.ts',
    plugins: [dts()],
  });
  await bundle.write({
    file: 'dist/index.d.ts',
    format: 'es',
  });
  console.log('DTS bundle written to dist/index.d.ts');
}

// ---------- Main ----------
(async () => {
  await analyzeAPI();
  await generateDocumentation();
  await bundleJS();
  await bundleDTS();
})();
