```javascript
/*  Source‑map helper – works in Node and in browsers
 *  Provides synchronous (Node only) and asynchronous APIs.
 *  Requires the “source-map” library in Node (npm install source-map)
 *  In browsers you can load the library from a CDN, e.g.:
 *    <script src="https://unpkg.com/source-map@0.7.4/dist/source-map.min.js"></script>
 */

(function (global) {
  const isNode = typeof process !== 'undefined' && process.versions != null && process.versions.node != null;
  const SourceMapConsumer = isNode
    ? require('source-map').SourceMapConsumer
    : (global.SourceMapConsumer || null);

  if (!SourceMapConsumer) {
    throw new Error('SourceMapConsumer not found. In Node: npm install source-map. In browsers: load source-map library.');
  }

  /**
   * Load a source map and its original sources.
   * @param {string} mapPathOrUrl - Path (Node) or URL (browser) to the source map.
   * @returns {Promise<{consumer: SourceMapConsumer, sources: Map<string,string>}>}
   */
  async function loadSourceMapAsync(mapPathOrUrl) {
    const mapText = await fetchText(mapPathOrUrl);
    const mapObj = JSON.parse(mapText);
    const consumer = await new SourceMapConsumer(mapObj);

    const sources = new Map();
    const baseUrl = getBaseUrl(mapPathOrUrl);

    // If sourcesContent is present, use it; otherwise fetch each source.
    if (Array.isArray(mapObj.sourcesContent)) {
      mapObj.sources.forEach((src, i) => {
        const content = mapObj.sourcesContent[i] || null;
        if (content !== null) sources.set(src, content);
      });
    }

    // Fetch missing sources
    const missing = mapObj.sources.filter(src => !sources.has(src));
    await Promise.all(
      missing.map(async src => {
        const srcUrl = new URL(src, baseUrl).toString();
        const content = await fetchText(srcUrl);
        sources.set(src, content);
      })
    );

    return { consumer, sources };
  }

  /**
   * Synchronous loader – only available in Node.
   * @param {string} mapPath - File system path to the source map.
   * @returns {{consumer: SourceMapConsumer, sources: Map<string,string>}}
   */
  function loadSourceMapSync(mapPath) {
    if (!isNode) throw new Error('Synchronous API is only available in Node.');
    const fs = require('fs');
    const path = require('path');

    const mapText = fs.readFileSync(mapPath, 'utf8');
    const mapObj = JSON.parse(mapText);
    const consumer = new SourceMapConsumer(mapObj);

    const sources = new Map();
    const baseDir = path.dirname(mapPath);

    // Use sourcesContent if available
    if (Array.isArray(mapObj.sourcesContent)) {
      mapObj.sources.forEach((src, i) => {
        const content = mapObj.sourcesContent[i] || null;
        if (content !== null) sources.set(src, content);
      });
    }

    // Read missing sources from disk
    const missing = mapObj.sources.filter(src => !sources.has(src));
    missing.forEach(src => {
      const srcPath = path.resolve(baseDir, src);
      const content = fs.readFileSync(srcPath, 'utf8');
      sources.set(src, content);
    });

    return { consumer, sources };
  }

  /**
   * Peek at the original source code for a given location.
   * @param {SourceMapConsumer} consumer
   * @param {Map<string,string>} sources
   * @param {string} file - The generated file name (as in the source map)
   * @param {number} line - 1‑based line number in the generated file
   * @param {number} column - 0‑based column number in the generated file
   * @returns {string|null} The original source snippet or null if not found
   */
  function peek(consumer, sources, file, line, column) {
    const pos = consumer.originalPositionFor({ source: file, line, column });
    if (!pos.source) return null;
    const src = sources.get(pos.source);
    if (!src) return null;
    const lines = src.split('\n');
    const origLine = pos.line - 1;
    if (origLine < 0 || origLine >= lines.length) return null;
    return lines[origLine];
  }

  /* ---------- Helper utilities ---------- */

  async function fetchText(url) {
    if (isNode) {
      const https = require('https');
      const http = require('http');
      const urlObj = new URL(url);
      const lib = urlObj.protocol === 'https:' ? https : http;
      return new Promise((resolve, reject) => {
        lib.get(url, res => {
          if (res.statusCode !== 200) return reject(new Error(`HTTP ${res.statusCode}`));
          let data = '';
          res.setEncoding('utf8');
          res.on('data', chunk => (data += chunk));
          res.on('end', () => resolve(data));
        }).on('error', reject);
      });
    } else {
      const resp = await fetch(url);
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      return await resp.text();
    }
  }

  function getBaseUrl(url) {
    if (isNode) {
      const path = require('path');
      return path.dirname(url) + '/';
    } else {
      const u = new URL(url, window.location.href);
      u.pathname = u.pathname.replace(/[^/]+$/, '');
      return u.toString();
    }
  }

  /* ---------- Public API ---------- */

  const SourceMapLoader = {
    loadAsync: loadSourceMapAsync,
    loadSync: loadSourceMapSync,
    peek: peek
  };

  // Export
  if (isNode) {
    module.exports = SourceMapLoader;
  } else {
    global.SourceMapLoader = SourceMapLoader;
  }
})(typeof window !== 'undefined' ? window : global);
