import {javascript} from "@codemirror/lang-javascript";
import {typescript} from "@codemirror/lang-typescript";
import {defaultKeymap, historyKeymap, history} from "@codemirror/commands";
import {autocompletion, completionKeymap} from "@codemirror/autocomplete";
import {oneDark} from "@codemirror/theme-one-dark";
import {indentOnInput} from "@codemirror/language";
import {closeBrackets, closeBracketsKeymap} from "@codemirror/autocomplete";
import {defaultHighlightStyle} from "@codemirror/language";
import {highlightSpecialChars} from "@codemirror/view";

// Custom keybindings
const customKeymap = [
  {key: "Ctrl-S", run: (view) => { console.log("Save triggered"); return true; }},
  {key: "Ctrl-/", run: (view) => { console.log("Toggle comment"); return true; }}
];

// Create the editor state
const state = EditorState.create({
  doc: `// TypeScript example\nconst greet = (name: string): string => {\n  return \`Hello, \${name}!\`;\n};`,
  extensions: [
    // Language support
    typescript(),
    // Syntax highlighting
    defaultHighlightStyle.fallback,
    // Theme
    oneDark,
    // Autocompletion
    autocompletion(),
    // Keymaps
    keymap.of([
      ...defaultKeymap,
      ...historyKeymap,
      ...completionKeymap,
      ...closeBracketsKeymap,
      ...customKeymap
    ]),
    // Other useful extensions
    history(),
    indentOnInput(),
    closeBrackets(),
    highlightSpecialChars()
  ]
});

// Create the editor view
const view = new EditorView({
  state,
  parent: document.getElementById("editor")
});
