// karma-mocha-adapter.js
// A minimal Karma framework adapter that exposes Mocha's BDD globals.

const Mocha = require('mocha');

module.exports = function (config) {
  return {
    // Register the framework under the name 'mocha'
    'framework:mocha': ['factory', function () {
      // Create a Mocha instance with the BDD interface
      const mocha = new Mocha({
        ui: 'bdd',
        reporter: 'spec'
      });

      // Expose the Mocha instance and BDD globals globally
      global.mocha = mocha;
      global.describe = mocha.suite.describe.bind(mocha.suite);
      global.it = mocha.suite.it.bind(mocha.suite);
      global.beforeEach = mocha.suite.beforeEach.bind(mocha.suite);
      global.afterEach = mocha.suite.afterEach.bind(mocha.suite);

      // Return the instance so Karma can use it if needed
      return mocha;
    }]
  };
};
```

**Usage**

1. Install the adapter as a dev dependency:

```bash
npm install --save-dev karma-mocha-adapter mocha
```

2. Add the adapter to your `karma.conf.js`:

```js
module.exports = function (config) {
  config.set({
    frameworks: ['mocha', 'karma-mocha-adapter'],
    files: [
      // Mocha library (if not loaded globally)
      'node_modules/mocha/mocha.js',
      // Your test files
      'test/**/*.spec.js'
    ],
    // ... other Karma config options ...
  });
};
```

This plugin registers the `mocha` framework with Karma and exposes the standard BDD globals (`describe`, `it`, `beforeEach`, `afterEach`) so you can write Mocha tests directly in your Karma test runner.

```js
// Requires the sqldb library (npm install sqldb)
const sqldb = require('sqldb');

/**
 * Executes a SQL query and returns a summary.
 *
 * @param {string} sql      The SQL query to execute.
 * @param {Array}  [params] Optional parameters for the query.
 * @returns {Promise<Object>} Summary of the execution.
 */
async function executeQuery(sql, params = []) {
  // Create a connection to the MySQL database
  const conn = sqldb.createConnection({
    host:     'localhost',
    user:     'root',
    password: 'your_password',
    database: 'your_database',
  });

  // Measure execution time
  const start = Date.now();

  // Execute the query (sqldb returns a promise if no callback is supplied)
  let result;
  try {
    result = await conn.query(sql, params);
  } catch (err) {
    conn.end();
    throw err;
  }

  const end = Date.now();
  const execTimeMs = end - start;

  // Determine affected rows by query type
  const firstWord = sql.trim().split(/\s+/)[0].toUpperCase();
  let inserted = 0, updated = 0, deleted = 0, affected = 0;

  if (result && typeof result.affectedRows === 'number') {
    affected = result.affectedRows;
    if (firstWord === 'INSERT') inserted = result.affectedRows;
    if (firstWord === 'UPDATE') updated = result.affectedRows;
    if (firstWord === 'DELETE') deleted = result.affectedRows;
  }

  // Close the connection
  conn.end();

  return {
    affectedRows: affected,
    inserted,
    updated,
    deleted,
    executionTimeMs: execTimeMs,
  };
}

