How to use multiple models with a single route in EmberJS / Ember Data?.

From reading the docs, it looks like you have to (or should) assign a model to a route like so:

App.PostRoute = Ember.Route.extend({
 model: function() {
 return App.Post.find();
 }
});

What if I need to use several objects in a certain route? i.e. Posts, Comments and Users? How do I tell the route to load those?

response_prompt:
```js
// app/routes/dashboard.js
import Route from '@ember/routing/route';
import { hash } from 'rsvp';

export default Route.extend({
  // Ember Data store is injected automatically
  model() {
    return hash({
      posts:    this.store.findAll('post'),     // App.Post.find()
      comments: this.store.findAll('comment'), // App.Comment.find()
      users:    this.store.findAll('user')      // App.User.find()
    });
  },

  // Optional: set each property on the controller for easier access
  setupController(controller, model) {
    this._super(controller, model);
    controller.setProperties({
      posts:    model.posts,
      comments: model.comments,
      users:    model.users
    });
  }
});
```

**Template usage**

```hbs
{{!-- app/templates/dashboard.hbs --}}
<h2>Posts</h2>
{{#each posts as |post|}}
  <div>{{post.title}}</div>
{{/each}}

<h2>Comments</h2>
{{#each comments as |comment|}}
  <div>{{comment.body}}</div>
{{/each}}

<h2>Users</h2>
{{#each users as |user|}}
  <div>{{user.name}}</div>
{{/each}}
```

The `hash` helper waits for all promises to resolve, so the route’s model is an object containing `posts`, `comments`, and `users`. You can also use `Ember.RSVP.all` if you prefer an array, but a hash gives you named properties that are easier to reference in the template.

