// app/routes/index.js
import Route from '@ember/routing/route';
import { hash } from 'rsvp';

export default class IndexRoute extends Route {
  // Load two unrelated models in parallel
  async model() {
    return hash({
      users: this.store.findAll('user'),      // first model
      posts: this.store.findAll('post')       // second model
    });
  }

  // Optional: expose the models as separate properties on the controller
  setupController(controller, model) {
    this._super(controller, model);
    controller.set('users', model.users);
    controller.set('posts', model.posts);
  }
}
```

