```javascript
// app/controllers/post.js
import Controller from '@ember/controller';

export default Controller.extend({
  // You can access the loaded data via `this.get('model.posts')`, etc.
});
```

```js
// app/routes/index.js
import Route from '@ember/routing/route';
import { service } from '@ember/service';

export default class IndexRoute extends Route {
  @service store;

  async model() {
    // load the first page
    return this.store.query('post', { page: 1, per_page: 20 });
  }
}
```

```js
// app/controllers/index.js
import Controller from '@ember/controller';
import { tracked } from '@glimmer/tracking';
import { task, timeout } from 'ember-concurrency';

export default class IndexController extends Controller {
  @tracked page = 1;
  @tracked loading = false;
  @tracked hasMore = true;

  @task
  *loadMore() {
    if (this.loading || !this.hasMore) { return; }

    this.loading = true;
    this.page += 1;

    try {
      const newPosts = yield this.store.query('post', {
        page: this.page,
        per_page: 20
      });

      // Ember Data will automatically merge the new records into the
      // existing array returned by the initial query.
      if (newPosts.length < 20) {
        this.hasMore = false; // no more pages
      }
    } finally {
      this.loading = false;
    }
  }

  // Debounce the scroll handler so we don't fire too often
  @task
  *debouncedLoadMore() {
    yield timeout(200);
    this.loadMore.perform();
  }
}
```

```js
// app/components/infinite-scroll.js
import Component from '@glimmer/component';
import { action } from '@ember/object';
import { inject as service } from '@ember/service';

export default class InfiniteScrollComponent extends Component {
  @service controller;

  @action
  handleScroll(event) {
    const { scrollTop, scrollHeight, clientHeight } = event.target;
    // If we are within 200px of the bottom, trigger loadMore
    if (scrollHeight - scrollTop - clientHeight < 200) {
      this.controller.debouncedLoadMore.perform();
    }
  }
}
```

```hbs
<!-- app/templates/index.hbs -->
<div
  class="post-list"
  style="height: 80vh; overflow-y: auto;"
  {{on "scroll" this.handleScroll}}
>
  {{#each this.model as |post|}}
    <article class="post">
      <h2>{{post.title}}</h2>
      <p>{{post.excerpt}}</p>
    </article>
  {{/each}}

  {{#if this.controller.loading}}
    <div class="loading">Loading…</div>
  {{/if}}

  {{#unless this.controller.hasMore}}
    <div class="end-of-list">No more posts</div>
  {{/unless}}
</div>
```

**How it works**

1. The route loads the first page of posts.  
2. The controller keeps track of the current page, whether a load is in progress, and if more pages exist.  
3. The `infinite-scroll` component listens for the `scroll` event on the container.  
4. When the user scrolls near the bottom, it calls the controller’s `debouncedLoadMore` task, which in turn calls `loadMore`.  
5. `loadMore` queries the next page; Ember Data merges the new records into the existing array, so the template automatically updates.  
6. When a page returns fewer records than requested, `hasMore` is set to `false` and the “No more posts” message is shown.

refinement_response:
@ember/controller: EXISTS – The Ember.js framework publishes a scoped package for controller utilities under the `@ember` namespace.  
@ember/object: EXISTS – This is the core Ember object model package, providing `EmberObject`, `Mixin`, etc.  
@ember/routing: EXISTS – Contains routing-related classes such as `Route`, `Router`, and `Transition`.  
@ember/service: EXISTS – Provides the service infrastructure (`Service`, `inject`, etc.) used throughout Ember applications.

request_prompt:
How should errors be handled when using the Ember.js Data RESTAdapter?.

ember-data.js: https://github.com/emberjs/data/tree/0396411e39df96c8506de3182c81414c1d0eb981

In short, when there is an error, I want to display error messages in the view, and then the user can 1) cancel, which will rollback the transaction 2) correct the input errors and successfully commit the transaction, passing the validations on the server.

Below is a code snippet from the source. It doesn't include an error callback.

updateRecord: function(store, type, record) {
 var id = get(record, 'id');
 var root = this.rootForType(type);

 var data = {};
 data[root] = this.toJSON(record);

 this.ajax(this.buildURL(root, id), "PUT", {
 data: data,
 context: this,
 success: function(json) {
 this.didUpdateRecord(store, type, record, json);
 }
 });
},

Overall, what is the flow of receiving an error from the server and updating the view? It seems that an error callback should put the model in an isError state, and then the view can display the appropriate messages. Also, the transaction should stay dirty. That way, the transaction can use rollback.

It seems that using store.recordWasInvalid is going in the right direction, though.

response_prompt:
```js
// app/adapters/application.js
import DS from 'ember-data';
import { get } from '@ember/object';

export default DS.RESTAdapter.extend({
  // Override the default updateRecord to add an error callback
  updateRecord(store, type, record) {
    let id   = get(record, 'id');
    let root = this.rootForType(type);

    let data = {};
    data[root] = this.toJSON(record);

    this.ajax(this.buildURL(root, id), 'PUT', {
      data,
      context: this,
      success(json) {
        this.didUpdateRecord(store, type, record, json);
      },
      error(xhr, textStatus, error) {
        // Parse the server error payload (assumed JSON)
        let payload = {};
        try {
          payload = JSON.parse(xhr.responseText);
        } catch (e) {
          payload = { errors: ['Unexpected server error'] };
        }
        // Tell the store that the record was invalid
        store.recordWasInvalid(record, payload);
      }
    });
  }
});
```

```js
// app/models/post.js
import DS from 'ember-data';

export default DS.Model.extend({
  title: DS.attr('string'),
  body:  DS.attr('string')
});
```

```js
// app/controllers/posts/edit.js
import Controller from '@ember/controller';
import { action } from '@ember/object';

export default Controller.extend({
  // The record is passed in via the route's model hook
  actions: {
    save() {
      this.get('model').save();
    },

    cancel() {
      // Rollback any unsaved changes
      this.get('model').rollback();
    }
  }
});
```

```hbs
<!-- app/templates/posts/edit.hbs -->
<form {{on "submit" (fn this.save)}}>
  <div>
    <label>Title</label>
    <input type="text" value={{this.model.title}} {{on "input" (fn (mut this.model.title) value)}} />
    {{#if this.model.errors.title}}
      <ul class="errors">
        {{#each this.model.errors.title as |err|}}
          <li>{{err}}</li>
        {{/each}}
      </ul>
    {{/if}}
  </div>

  <div>
    <label>Body</label>
    <textarea {{on "input" (fn (mut this.model.body) value)}}>{{this.model.body}}</textarea>
    {{#if this.model.errors.body}}
      <ul class="errors">
        {{#each this.model.errors.body as |err|}}
          <li>{{err}}</li>
        {{/each}}
      </ul>
    {{/if}}
  </div>

  <button type="submit">Save</button>
  <button type="button" {{on "click" (fn this.cancel)}}>Cancel</button>
</form>
```

**Key points**

* `store.recordWasInvalid(record, payload)` puts the record into an *invalid* state and populates `record.errors` with the payload.
* The view can read `record.errors` (or `record.get('errors')`) to show validation messages.
* The record remains *dirty*; calling `record.rollback()` restores the original values and clears the errors.

request_prompt:
How should errors be handled when using the Ember.js Data RESTAdapter?.

ember-data.js: https://github.com/emberjs/data/tree/0396411e39df96c8506de3182c81414c1d0eb981

In short, when there is an error, I want to display error messages in the view, and then the user can 1) cancel, which will rollback the transaction 2) correct the input errors and successfully commit the transaction, passing the validations on the server.

Below is a code snippet from the source. It doesn't include an error callback.

updateRecord: function(store, type, record) {
 var id = get(record, 'id');
 var root = this.rootForType(type);

 var data = {};
 data[root] = this.toJSON(record);

 this.ajax(this.buildURL(root, id), "PUT", {
 data: data,
 context: this,
 success: function(json) {
 this.didUpdateRecord(store, type, record, json);
 }
 });
},

Overall, what is the flow of receiving an error from the server and updating the view? It seems that an error callback should put the model in an isError state, and then the view can display the appropriate messages. Also, the transaction should stay dirty. That way, the transaction can use rollback.

It seems that using store.recordWasInvalid is going in the right direction, though.

response_prompt:
```js
// app/adapters/application.js
import RESTAdapter from '@ember-data/adapter/rest';
import { get } from '@ember/object';

export default class ApplicationAdapter extends RESTAdapter {
  /**
   * Override the default updateRecord to add error handling.
   */
  updateRecord(store, type, record) {
    const id   = get(record, 'id');
    const root = this.rootForType(type);

    const data = {};
    data[root] = this.toJSON(record);

    // Pass the record in the context so we can access it in the error handler
    return this.ajax(this.buildURL(root, id), 'PUT', {
      data,
      context: { record }
    })
    .then((json) => {
      this.didUpdateRecord(store, type, record, json);
    })
    .catch((error) => {
      // Ember Data 2.x+ returns a Response object; use responseJSON if available
      const errors = error.responseJSON || error.body || {};

      // Tell the store that the record was invalid
      this.store.recordWasInvalid(record, errors);

      // Re‑throw so that the promise chain knows the request failed
      throw error;
    });
  }

  /**
   * Optional: override ajax to add a global error handler for all requests.
   */
  ajax(url, method, options) {
    return super.ajax(url, method, options).catch((error) => {
      // If the request had a record in its context, mark it as invalid
      const record = options?.context?.record;
      if (record) {
        const errors = error.responseJSON || error.body || {};
        this.store.recordWasInvalid(record, errors);
      }
      throw error;
    });
  }
}
