  @service router;

  constructor() {
    super(...arguments);
    this.router.on('routeDidChange', this._trackPageView, this);
  }

  _trackPageView(transition) {
    // Build a virtual page path
    const url = transition.to?.url || transition.intent?.url || window.location.pathname;
    // Push to GTM dataLayer
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
