```js
// npm-error-summary.js
// A tiny helper that reads an npm error log from stdin and prints a concise summary.
// Usage: npm install | node npm-error-summary.js

const fs = require('fs');
const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});

let lines = [];
rl.on('line', line => lines.push(line));

rl.on('close', () => {
  const errorText = lines.join('\n');
  const match = errorText.match(/npm ERR! (.+)/g);
  if (!match) {
    console.log('No npm error detected.');
    return;
  }

  console.log('=== npm Error Summary ===');
  match.forEach(err => console.log(err.trim()));
  console.log('=== End of Summary ===');
});
```

