// Load the dataset in streaming mode – this avoids downloading the whole
// dataset to disk.  We then take only the first N rows (≈10 % of the data
// if you know the total size, otherwise just a fixed number).
import { loadDataset, DownloadConfig } from '@huggingface/datasets';

// Optional: limit the size of each shard that will be downloaded
const downloadConfig = new DownloadConfig({ maxShardSize: '10MB' });

async function getSubset() {
  // Streaming train split
  const trainStream = await loadDataset(
    'MLCommons/peoples_speech',
    'clean',
    { split: 'train', streaming: true, downloadConfig }
  );

  // Take the first 10 000 rows (adjust as needed)
  const trainSubset = trainStream.take(10000).toDataset();

  // Streaming test split
  const testStream = await loadDataset(
    'MLCommons/peoples_speech',
    'clean',
    { split: 'test', streaming: true, downloadConfig }
  );

  const testSubset = testStream.take(10000).toDataset();

  return { trainSubset, testSubset };
}

getSubset().then(({ trainSubset, testSubset }) => {
  console.log('Train subset size:', trainSubset.length);
  console.log('Test subset size:', testSubset.length);
});
```

