  "private": true,
  "dependencies": {
    "dependency-A": "0.1.0",
    "dependency-B": "0.1.0"
  }
}
```

```js
// packages/main-package/webpack.config.js
const path = require('path');
const CopyWebpackPlugin = require('copy-webpack-plugin');

module.exports = {
  // … your other config …
  plugins: [
    new CopyWebpackPlugin({
      patterns: [
        {
          // Copy media from dependency‑A
          from: path.resolve(__dirname, '../../dependency-A/media'),
          to: path.resolve(__dirname, 'static/dependency-A-media')
        },
        {
          // Copy research‑data.json from dependency‑B
          from: path.resolve(__dirname, '../../dependency-B/dist/research-data.json'),
          to: path.resolve(__dirname, 'static/research-data.json')
        }
      ]
    })
  ]
};
```

