import { action, on } from '@ember/object';
import { task } from 'ember-concurrency';
import FetchService from 'hermes/services/fetch';
import { inject as service } from '@ember/service';

type TeamArea = {
  abbreviation: string;
  perDocDataType: unknown;
  BU: string;
};

type TeamAreas = Record<string, TeamArea>;

export default class InputsTeamSelectComponent extends Component {
  @service('fetch') declare fetchSvc: FetchService;

  /** The BU that comes from the parent component */
  @tracked selectedBU: string | null = this.args.selectedBU ?? null;

  /** The list of teams that match the current BU */
  @tracked teams: TeamAreas | undefined = undefined;

  /** The currently selected team key */
  @tracked selected: string | undefined = this.args.selected;

  /** ------------------------------------------------------------------
   *  Whenever the parent changes the `selectedBU` argument we want to
   *  re‑fetch the teams.  The `@on('didUpdate')` hook runs after every
   *  render, so we can compare the new argument with the tracked value
   *  and trigger a fetch only when it actually changed.
   * ------------------------------------------------------------------ */
  @on('didUpdate')
  @action
  updateSelectedBU() {
    const newBU = this.args.selectedBU ?? null;
    if (newBU !== this.selectedBU) {
      this.selectedBU = newBU;
      this.fetchTeams.perform();
    }
  }

  /** ------------------------------------------------------------------
   *  The task that talks to the API and filters the teams by BU.
   * ------------------------------------------------------------------ */
  fetchTeams = task(async () => {
    try {
      const allTeams = await this.fetchSvc
        .fetch('/api/v1/teams')
        .then((r) => r?.json() as TeamAreas);

      const filtered: TeamAreas = {};

      for (const key of Object.keys(allTeams)) {
        const team = allTeams[key];
        if (team.BU === this.selectedBU) {
          filtered[key] = team;
        }
      }

      this.teams = filtered;
    } catch (e) {
      console.error('Failed to load teams', e);
      this.teams = undefined;
    }
  });

  /** ------------------------------------------------------------------
   *  Called when the user selects a team from the dropdown.
   * ------------------------------------------------------------------ */
  @action
  onChange(newKey: string) {
    this.selected = newKey;
    this.args.onChange?.(newKey, this.teams?.[newKey]);
  }

  /** ------------------------------------------------------------------
   *  Helper to expose the abbreviation of the selected team.
   * ------------------------------------------------------------------

