// app/serializers/user.js
import ApplicationSerializer from './application';

export default class UserSerializer extends ApplicationSerializer {
  // If the API returns a root key like `user` instead of `users`,
  // normalize it here.
  normalizeResponse(store, primaryModelClass, payload, id, requestType) {
    if (payload.user) {
      payload.users = [payload.user];
      delete payload.user;
    }
    return super.normalizeResponse(store, primaryModelClass, payload, id, requestType);
  }
}
```

```js
// app/serializers/repo.js
import ApplicationSerializer from './application';

export default class RepoSerializer extends ApplicationSerializer {
  // If the API returns a root key like `repo` instead of `repos`,
  // normalize it here.
  normalizeResponse(store, primaryModelClass, payload, id, requestType) {
    if (payload.repo) {
      payload.repos = [payload.repo];
      delete payload.repo;
    }
    return super.normalizeResponse(store, primaryModelClass, payload, id, requestType);
  }
}
```

```js
// app/routes/dashboard.js
import Route from '@ember/routing/route';
import { Promise } from 'rsvp';

export default class DashboardRoute extends Route {
  model() {
    // Fetch users and repos in parallel
    return Promise.all([
      this.store.findAll('user'),
      this.store.findAll('repo')
    ]).then(([users, repos]) => {
      return { users, repos };
    });
  }
}
```

```js
// app/templates/dashboard.hbs
<h2>Users</h2>
<ul>
  {{#each this.model.users as |user|}}
    <li>{{user.name}} ({{user.email}})</li>
  {{/each}}
</ul>

<h2>Repos</h2>
<ul>
  {{#each this.model.repos as |repo|}}
    <li>{{repo.name}} – {{repo.description}}</li>
  {{/each}}
</ul>
```

**Explanation**

* Each model (`user`, `repo`) has its own adapter and serializer.  
* The adapters override `pathForType()` so Ember Data hits `/users` and `/repos` respectively.  
* The serializers normalize the payload if the API returns singular root keys (`user`, `repo`).  
* In the route, `store.findAll('user')` and `store.findAll('repo')` are called separately; Ember Data keeps them in their own namespaces, so the inspector will show two distinct record types.

`findAll()` returns a **live array** that is kept in the Ember‑Data store.  
When the store receives a new record it simply pushes it to the end of that
array – it does **not** reorder the array to match the order that the API
returned.  
So after you call `/addName` the store already has the old records in the
order they were fetched (`["A","D","Z"]`) and the new record (`"B"`) is
appended, giving `["A","D","Z","B"]`.

To get the array in the order you want you have to either:

1. **Force a fresh fetch** (so the store rebuilds the array from the API
   response)  
   ```js
   // controller or component
   this.store.findAll('name', { reload: true }).then(names => {
     // names is now sorted as returned by the API
   });
   ```

2. **Sort the array yourself** (recommended if you want the array to stay
   live)  
   ```js
   // app/controllers/names.js
   import Controller from '@ember/controller';
   import { sort } from '@ember/object/computed';

   export default class NamesController extends Controller {
     // Assuming the model is an array of name records
     @sort('model.@each.name', function(a, b) {
       return a.name.localeCompare(b.name);
     }) sortedNames;
   }
   ```

3. **Use a query instead of `findAll`** and let the adapter send a sort
   parameter that the backend honors.  
   ```js
   // app/adapters/name.js
   import RESTAdapter from '@ember-data/adapter/rest';

   export default class NameAdapter extends RESTAdapter {
     buildURL() {
       return super.buildURL(...arguments) + '?sort=name';
     }
   }

   // controller
   this.store.query('name', {}).then(names => {
     // names are already sorted
   });
   ```

Any of the above will give you a correctly ordered array after adding a new
record.

```js
// ── main.js ────────────────────────────────────────────────────────────────
const path = require('path');

// 1️⃣  Tell Node where the project‑root “src” folder lives
process.env.NODE_PATH = path.join(__dirname, 'src');

// 2️⃣  Re‑initialise the module search paths so that NODE_PATH is honoured
require('module').Module._initPaths();

// 3️⃣  Now we can `require` modules using a path that starts at the project root
const Worker = require('a1/a2/a3/Worker.js');

Worker.doWork();
```

```js
// ── src/a1/a2/a3/Worker.js ───────────────────────────────────────────────
const SubWorker = require('subFolder1/SubWorker.js');

module.exports = class Worker {
  static doWork() {
    console.log('doing work');
    SubWorker.doMoreWork();
  }
};
```

```js
// ── src/subFolder1/SubWorker.js ───────────────────────────────────────────
module.exports = class SubWorker {
  static doMoreWork() {
    console.log('doing more work');
  }
};
```

**How it works**

1. `process.env.NODE_PATH` is set to the absolute path of the project‑root `src` directory.  
2. `require('module').Module._initPaths()` forces Node to rebuild its internal module‑search list so that the new `NODE_PATH` value is used.  
3. After that, any `require('…')` call that starts with a path relative to the project root (e.g. `'subFolder1/SubWorker.js'`) is resolved correctly, without needing any relative `../` segments.

**Running the code**

```bash
node main.js
```

The output will be:

```
doing work
doing more work
```

This satisfies all the stated requirements:

* No external packages are used.  
* Imports are written with project‑root paths.  
* IDEs that understand Node’s module resolution (e.g., WebStorm, VS Code) will recognise the paths and provide “Go to Declaration” and refactor‑move support.

